service.method:

DELETE FROM
	UCONF
WHERE
	HOUSE_CODE = ${CLIENT_CODE}
AND COMPANY_CODE = ${COMPANY_CODE}
AND `GROUP` = ${GROUP}


INSERT INTO UCONF
(
	  HOUSE_CODE
	, COMPANY_CODE
	, `KEY`
	, VALUE
	, `GROUP`
	, ADD_USER_ID
	, ADD_DATE
	, ADD_TIME
	, CHANGE_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
	, DEL_FLAG
)
VALUES
(
	  ${CLIENT_CODE}
	, ${COMPANY_CODE}
	, ${KEY}
	, ${VALUE}
	, ${GROUP}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, 'N'
)
